#include <cstdint>
#include <optional>
#include <string>
#include <vector>

struct Section { std::string name; std::uint32_t virtualAddress, virtualSize, rawPointer, rawSize, characteristics; };
struct Import { std::string dll; std::string function; std::uint16_t ordinal; };

class PeFile
{
public:
    bool load(std::vector<std::uint8_t> bytes)
    {
        file.clear(); list.clear(); entry = 0; base = 0; importRva = 0;
        if (bytes.size() < 0x40 || bytes[0] != 'M' || bytes[1] != 'Z') return false;
        file = std::move(bytes);
        const std::uint64_t pe{ le(0x3C, 4) };
        if (pe + 24 > file.size() || le(static_cast<std::size_t>(pe), 4) != 0x4550) return fail();
        const std::size_t fh{ static_cast<std::size_t>(pe) + 4 }, opt{ fh + 20 };
        const std::size_t count{ static_cast<std::size_t>(le(fh + 2, 2)) }, optSize{ static_cast<std::size_t>(le(fh + 16, 2)) };
        if (opt + 128 > file.size() || le(opt, 2) != 0x20B) return fail();
        const std::size_t table{ opt + optSize };
        if (table + count * 40 > file.size()) return fail();
        entry = static_cast<std::uint32_t>(le(opt + 16, 4));
        base = le(opt + 24, 8);
        importRva = static_cast<std::uint32_t>(le(opt + 120, 4));
        for (std::size_t i{ 0 }; i < count; ++i)
        {
            const std::size_t at{ table + i * 40 };
            Section s{};
            for (int k{ 0 }; k < 8 && file[at + k] != 0; ++k) s.name += static_cast<char>(file[at + k]);
            s.virtualSize = static_cast<std::uint32_t>(le(at + 8, 4));
            s.virtualAddress = static_cast<std::uint32_t>(le(at + 12, 4));
            s.rawSize = static_cast<std::uint32_t>(le(at + 16, 4));
            s.rawPointer = static_cast<std::uint32_t>(le(at + 20, 4));
            s.characteristics = static_cast<std::uint32_t>(le(at + 36, 4));
            list.push_back(s);
        }
        return true;
    }

    std::uint32_t entryPoint() const { return entry; }
    std::uint64_t imageBase() const { return base; }
    const std::vector<Section>& sections() const { return list; }

    std::optional<std::uint32_t> rvaToOffset(std::uint32_t rva) const
    {
        const Section* s{ find(rva) };
        if (!s || rva - s->virtualAddress >= s->rawSize) return std::nullopt;
        const std::uint32_t offset{ rva - s->virtualAddress + s->rawPointer };
        if (offset >= file.size()) return std::nullopt;
        return offset;
    }

    std::string sectionOf(std::uint32_t rva) const { const Section* s{ find(rva) }; return s ? s->name : ""; }

    std::string permissions(const Section& s) const
    {
        return std::string{ (s.characteristics & 0x40000000u) ? 'r' : '-', (s.characteristics & 0x80000000u) ? 'w' : '-', (s.characteristics & 0x20000000u) ? 'x' : '-' };
    }

    std::vector<Import> imports() const
    {
        std::vector<Import> out;
        if (!importRva) return out;
        for (std::uint32_t d{ importRva };; d += 20)
        {
            const auto at{ rvaToOffset(d) };
            if (!at || *at + 20 > file.size()) return out;
            const std::uint32_t oft{ static_cast<std::uint32_t>(le(*at, 4)) }, nameRva{ static_cast<std::uint32_t>(le(*at + 12, 4)) }, ft{ static_cast<std::uint32_t>(le(*at + 16, 4)) };
            if (oft == 0 && nameRva == 0 && ft == 0) return out;
            const auto dll{ text(nameRva) };
            if (!dll) return out;
            for (std::uint32_t t{ oft ? oft : ft };; t += 8)
            {
                const auto tat{ rvaToOffset(t) };
                if (!tat || *tat + 8 > file.size()) return out;
                const std::uint64_t thunk{ le(*tat, 8) };
                if (thunk == 0) break;
                if (thunk & 0x8000000000000000ull) out.push_back({ *dll, "", static_cast<std::uint16_t>(thunk & 0xFFFF) });
                else
                {
                    const auto name{ text(static_cast<std::uint32_t>(thunk) + 2) };
                    if (!name) return out;
                    out.push_back({ *dll, *name, 0 });
                }
            }
        }
    }

private:
    std::vector<std::uint8_t> file;
    std::vector<Section> list;
    std::uint32_t entry{ 0 };
    std::uint64_t base{ 0 };
    std::uint32_t importRva{ 0 };

    bool fail() { file.clear(); list.clear(); return false; }

    std::uint64_t le(std::size_t at, int n) const
    {
        std::uint64_t v{ 0 };
        for (int i{ 0 }; i < n; ++i) v |= static_cast<std::uint64_t>(file[at + i]) << (8 * i);
        return v;
    }

    const Section* find(std::uint32_t rva) const
    {
        for (const Section& s : list)
            if (rva >= s.virtualAddress && rva - s.virtualAddress < s.virtualSize) return &s;
        return nullptr;
    }

    std::optional<std::string> text(std::uint32_t rva) const
    {
        const auto at{ rvaToOffset(rva) };
        if (!at) return std::nullopt;
        std::string s;
        for (std::size_t i{ *at }; i < file.size() && file[i] != 0; ++i) s += static_cast<char>(file[i]);
        return s;
    }
};

