#include <cstring>
using Bytes = std::vector<std::uint8_t>;
static void put(Bytes& b, std::size_t at, std::uint64_t v, int n) { for (int i{ 0 }; i < n; ++i) b[at + i] = static_cast<std::uint8_t>(v >> (8 * i)); }
// RVAs in .rdata (VA 0x2000) live at file offset rva - 0x2000 + 0x600.
static std::size_t off(std::uint32_t rva) { return rva - 0x2000 + 0x600; }
static void str(Bytes& b, std::uint32_t rva, const char* s) { std::memcpy(&b[off(rva)], s, std::strlen(s) + 1); }

static Bytes sample(bool secondHasNoInt = false)
{
    Bytes b(0x800, 0);
    b[0] = 'M'; b[1] = 'Z'; put(b, 0x3C, 0x80, 4);
    b[0x80] = 'P'; b[0x81] = 'E';
    put(b, 0x84, 0x8664, 2); put(b, 0x86, 3, 2); put(b, 0x94, 0xF0, 2);
    put(b, 0x98, 0x20B, 2); put(b, 0x98 + 16, 0x1010, 4); put(b, 0x98 + 24, 0x140000000, 8); put(b, 0x98 + 108, 16, 4);
    put(b, 0x98 + 120, 0x2000, 4); put(b, 0x98 + 124, 0x3C, 4);
    const struct { const char* n; std::uint32_t va, vs, raw, rs, ch; } secs[]{
        { ".text", 0x1000, 0x1A0, 0x400, 0x200, 0x60000020 },
        { ".rdata", 0x2000, 0x200, 0x600, 0x200, 0x40000040 },
        { ".data", 0x3000, 0x80, 0, 0, 0xC0000040 } };
    for (int i{ 0 }; i < 3; ++i)
    {
        const std::size_t at{ 0x188 + static_cast<std::size_t>(i) * 40 };
        std::memcpy(&b[at], secs[i].n, std::strlen(secs[i].n));
        put(b, at + 8, secs[i].vs, 4); put(b, at + 12, secs[i].va, 4); put(b, at + 16, secs[i].rs, 4); put(b, at + 20, secs[i].raw, 4); put(b, at + 36, secs[i].ch, 4);
    }
    // descriptors: KERNEL32 (INT 0x2060, IAT 0x20A0) and WS2_32 (INT 0x2080, IAT 0x20C0), then a zero one
    put(b, off(0x2000), 0x2060, 4); put(b, off(0x2000) + 12, 0x2040, 4); put(b, off(0x2000) + 16, 0x20A0, 4);
    put(b, off(0x2014), secondHasNoInt ? 0 : 0x2080, 4); put(b, off(0x2014) + 12, 0x2050, 4); put(b, off(0x2014) + 16, 0x20C0, 4);
    str(b, 0x2040, "KERNEL32.dll"); str(b, 0x2050, "WS2_32.dll");
    for (std::uint32_t table : { 0x2060u, 0x20A0u }) { put(b, off(table), 0x2100, 8); put(b, off(table) + 8, 0x2110, 8); }
    for (std::uint32_t table : { 0x2080u, 0x20C0u }) { put(b, off(table), 0x8000000000000017ull, 8); put(b, off(table) + 8, 0x2120, 8); }
    put(b, off(0x2100), 0x10, 2); str(b, 0x2102, "CreateFileW");
    put(b, off(0x2110), 0x20, 2); str(b, 0x2112, "ReadFile");
    put(b, off(0x2120), 0x05, 2); str(b, 0x2122, "send");
    return b;
}

TEST("loading") {
    PeFile pe;
    CHECK(pe.load(sample()));
    CHECK_EQ(pe.entryPoint(), 0x1010u);
    CHECK_EQ(pe.imageBase(), 0x140000000ull);
    CHECK_EQ(pe.sections().size(), 3u);
    Bytes bad{ sample() }; bad[0x80] = 'X';
    PeFile broken;
    CHECK(!broken.load(bad));
    CHECK(broken.sections().empty());
    CHECK(!broken.load(Bytes(0x20, 0)));
}
TEST("sections and permissions") {
    PeFile pe;
    pe.load(sample());
    if (pe.sections().size() != 3) { CHECK(false); return; }
    CHECK_EQ(pe.permissions(pe.sections()[0]), std::string("r-x"));
    CHECK_EQ(pe.permissions(pe.sections()[1]), std::string("r--"));
    CHECK_EQ(pe.permissions(pe.sections()[2]), std::string("rw-"));
    CHECK_EQ(pe.sectionOf(0x1010), std::string(".text"));
    CHECK_EQ(pe.sectionOf(0x3040), std::string(".data"));
    CHECK_EQ(pe.sectionOf(0x9000), std::string(""));
    CHECK_EQ(pe.rvaToOffset(0x2110).value_or(0), 0x710u);
    CHECK(!pe.rvaToOffset(0x3040).has_value());
}
TEST("imports") {
    PeFile pe;
    pe.load(sample());
    const auto list{ pe.imports() };
    CHECK_EQ(list.size(), 4u);
    if (list.size() != 4) return;
    CHECK_EQ(list[0].dll, std::string("KERNEL32.dll")); CHECK_EQ(list[0].function, std::string("CreateFileW"));
    CHECK_EQ(list[1].function, std::string("ReadFile"));
    CHECK_EQ(list[2].dll, std::string("WS2_32.dll")); CHECK_EQ(list[2].function, std::string("")); CHECK_EQ(list[2].ordinal, 0x17);
    CHECK_EQ(list[3].function, std::string("send")); CHECK_EQ(list[3].ordinal, 0);
}
TEST("falling back to the IAT") {
    PeFile pe;
    pe.load(sample(true));
    const auto list{ pe.imports() };
    CHECK_EQ(list.size(), 4u);
    if (list.size() == 4) CHECK_EQ(list[3].function, std::string("send"));
}
TEST("a broken import table stops cleanly") {
    Bytes b{ sample() };
    put(b, off(0x2014) + 12, 0x7000, 4);
    PeFile pe;
    pe.load(b);
    CHECK_EQ(pe.imports().size(), 2u);
}

